(()=>{const path=location.pathname;const nested=/\/events\//.test(path);const prefix=nested?"../":"";const lang=()=>document.documentElement.lang==="en"?"en":"fr";const apiBase="https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1";const page=path.split("/").pop()||"index.html";const pageClass=(()=>{if(page==="index.html"||page==="")return"premium-page-home";if(page==="classement.html")return"premium-page-ranking";if(page==="reglement.html")return"premium-page-rules";if(page==="gtworld.html")return"premium-page-gtworld";if(page==="daily-race.html")return"premium-page-daily";if(page==="open-lobby.html")return"premium-page-open-lobby";if(page==="calendrier.html")return"premium-page-calendar";if(page==="archives.html")return"premium-page-archives";if(page==="profil-pilote.html")return"premium-page-profile";if(page==="course.html"||nested)return"premium-page-course";if(page==="event-admin.html")return"premium-page-admin";if(page==="confidentialite.html")return"premium-page-privacy";return"premium-page-generic"})();document.body.classList.add("premium-site",pageClass);const isActive=href=>{const[targetLocation,targetHash=""]=href.split("#");const targetPage=targetLocation.split("?")[0];const currentHash=location.hash.replace("#","")||"points";if(targetPage==="index.html")return page===""||page==="index.html";if(targetPage==="classement.html"&&targetHash)return page===targetPage&&currentHash===targetHash;return page===targetPage};const nav=document.querySelector(".side-links");const racePages={WGT:"gtworld.html",DR:"daily-race.html",OL:"open-lobby.html"};const raceCategory=()=>{if(page==="gtworld.html")return"WGT";if(page==="daily-race.html")return"DR";if(page==="open-lobby.html")return"OL";if(page==="course.html"||nested)return document.querySelector("[data-public-event]")?.dataset.eventCategory||null;return null};const activeKey=()=>{const category=raceCategory();if(category)return category;if(page==="classement.html"&&["circuit","driver"].includes(location.hash.slice(1)))return location.hash.slice(1);if(page==="index.html"||page==="")return"home";if(page==="archives.html")return"archives";if(page==="reglement.html")return"rules";return""};const links=[["index.html","Accueil","Home","home"],["gtworld.html","WorldGT","WorldGT","WGT"],["daily-race.html","Daily Race","Daily Race","DR"],["open-lobby.html","Open Lobby","Open Lobby","OL"],["archives.html","Archives","Archives","archives"],["reglement.html","Règlement","Rules","rules"]];let navLinks=[];if(nav){nav.classList.add("fx-primary-nav");nav.setAttribute("aria-label","Navigation principale");navLinks=links.map(([href,fr,en,key])=>{const link=document.createElement("a");link.href=prefix+href;link.dataset.fr=fr;link.dataset.en=en;link.dataset.fxSection=key;link.textContent=lang()==="en"?en:fr;return link});const times=document.createElement("div");times.className="fx-times-nav";const heading=document.createElement("span");heading.dataset.fr="Meilleurs temps";heading.dataset.en="Best lap times";heading.textContent=lang()==="en"?"Best lap times":"Meilleurs temps";times.append(heading);for(const[href,fr,en,key]of [["classement.html#circuit","Par circuit","By circuit","circuit"],["classement.html#driver","Par pilote","By driver","driver"]]){const link=document.createElement("a");link.href=prefix+href;link.dataset.fr=fr;link.dataset.en=en;link.dataset.fxSection=key;link.textContent=lang()==="en"?en:fr;times.append(link);navLinks.push(link)}nav.replaceChildren(...navLinks.slice(0,4),times,...navLinks.slice(4,6))}const syncNav=()=>{const key=activeKey();for(const link of navLinks){const on=link.dataset.fxSection===key;link.classList.toggle("active",on);if(on)link.setAttribute("aria-current","page");else link.removeAttribute("aria-current")}const times=nav?.querySelector(".fx-times-nav");if(times)times.classList.toggle("active",key==="circuit"||key==="driver")};const setupTabs=()=>{const root=document.querySelector("[data-course-page]");if(!root)return;const tabs=root.querySelector(".fx-course-tabs");if(!tabs)return;const anchors=[...tabs.querySelectorAll('a[href^="#"]')];const setActive=()=>{let selected=location.hash.slice(1);if(!["concept","calendrier","classement"].includes(selected))selected="concept";for(const link of anchors){const on=link.hash==="#"+selected;link.classList.toggle("active",on);if(on)link.setAttribute("aria-current","location");else link.removeAttribute("aria-current")}};setActive();window.addEventListener("hashchange",setActive);if("IntersectionObserver"in window){const observer=new IntersectionObserver(entries=>{if(location.hash)return;for(const entry of entries)if(entry.isIntersecting){anchors.forEach(link=>link.classList.toggle("active",link.hash==="#"+entry.target.id));}},{rootMargin:"-22% 0px -63% 0px",threshold:0});for(const id of ["concept","calendrier","classement"]){const section=root.querySelector("#"+id);if(section)observer.observe(section)}}};setupTabs();syncNav();window.addEventListener("hashchange",syncNav);document.addEventListener("atx:eventcategory",syncNav);document.addEventListener("atx:rankingcategory",syncNav);
const footer=document.querySelector(".site-footer");if(footer){footer.innerHTML=`<div class="wrap"><div class="premium-footer-grid"><div><a class="brand" href="${prefix}index.html">ATX <span>Racing</span></a><p class="premium-footer-copy" data-fr="Compétition ACC, événements, classements et progression pilote — une identité ATX Motorsport." data-en="ACC competition, events, standings and driver progression — an ATX Motorsport identity.">Compétition ACC, événements, classements et progression pilote — une identité ATX Motorsport.</p></div><nav class="premium-footer-links" aria-label="Footer"><a href="${prefix}index.html">Accueil</a><a href="${prefix}gtworld.html">WorldGT</a><a href="${prefix}daily-race.html">Daily Race</a><a href="${prefix}open-lobby.html">Open Lobby</a><a href="${prefix}gtworld.html#calendrier">Calendrier WorldGT</a><a href="${prefix}gtworld.html#classement">Classement WorldGT</a><a href="${prefix}archives.html">Archives</a><a href="${prefix}reglement.html">Règlement</a><a href="https://www.thesimgrid.com/communities/atxracing" target="_blank" rel="noopener">SimGrid</a><a href="https://discord.gg/dgyJJYTSsD" target="_blank" rel="noopener">Discord</a><a href="${prefix}confidentialite.html">Confidentialité</a></nav></div><div class="premium-footer-legal"><span>© 2026 ATX Racing · ATX Motorsport</span><a href="mailto:athoxmotorsport@gmail.com">athoxmotorsport@gmail.com</a></div></div>`}const main=document.querySelector("main");let ticker=main?.querySelector(".live-ticker");if(main&&!ticker){ticker=document.createElement("div");ticker.className="live-ticker premium-global-ticker";ticker.setAttribute("aria-label","Informations ATX Racing");ticker.innerHTML='<div class="live-ticker-track" data-premium-ticker-track></div>';main.prepend(ticker)}const track=ticker?.querySelector(".live-ticker-track");const localDate=value=>new Intl.DateTimeFormat(lang()==="en"?"en-GB":"fr-BE",{dateStyle:"medium",timeStyle:"short",timeZone:"Europe/Brussels"}).format(new Date(value));const renderTicker=events=>{if(!track)return;const now=Date.now();const next=(events||[]).filter((e=>new Date(e.starts_at).getTime()>=now)).sort(((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)))[0];const messages=next?[lang()==="en"?`Next event · ${next.title||next.title_fr||next.circuit_name||"ATX Racing"}`:`Prochain événement · ${next.title||next.title_fr||next.circuit_name||"ATX Racing"}`,localDate(next.starts_at),lang()==="en"?"Registration via SimGrid":"Inscriptions via SimGrid",lang()==="en"?"Official results · Performance · SAFE":"Résultats officiels · Performance · SAFE","Assetto Corsa Competizione · GT3"]:[lang()==="en"?"ATX Racing · Next event in preparation":"ATX Racing · Prochain événement en préparation",lang()==="en"?"Calendar and registration via SimGrid":"Calendrier et inscriptions via SimGrid",lang()==="en"?"Official results · Performance · SAFE":"Résultats officiels · Performance · SAFE","Assetto Corsa Competizione · GT3"];const fragment=document.createDocumentFragment();for(let copy=0;copy<2;copy+=1){messages.forEach((message=>{const item=document.createElement("span");item.className="live-ticker-item";item.textContent=message;fragment.append(item)}))}track.replaceChildren(fragment)};if(track)fetch(`${apiBase}/public-event`,{cache:"no-store"}).then((r=>r.ok?r.json():Promise.reject())).then((p=>renderTicker(p.events||[]))).catch((()=>renderTicker([])));const circuitHeading=document.querySelector('[data-ranking-panel="circuit"] .ranking-panel-head h2');if(circuitHeading)circuitHeading.innerHTML='<span class="premium-red">CLASSEMENT</span><br>MEILLEURS TOURS <span class="premium-outline">PAR CIRCUIT</span>';const decorateSectionHeadings=()=>{document.querySelectorAll("main section .wrap").forEach((wrap=>{const label=wrap.querySelector(":scope > .section-label");const heading=wrap.querySelector(":scope > h1, :scope > h2");if(label&&heading)wrap.classList.add("premium-section-heading")}))};decorateSectionHeadings();const fixRedBullRingImage=()=>{document.querySelectorAll(".circuit-visual-card").forEach((card=>{const name=card.querySelector(".circuit-card-name")?.textContent?.trim().toLowerCase()||"";if(!name.includes("red bull ring"))return;const img=card.querySelector(".circuit-card-media img");if(!img)return;const replacement="https://gdm-universal-media.b-cdn.net/racinggames/77340ace8cf3f6e652f0d196344d7d7a304b9083-3840x2160.jpg?height=840&width=1600";if(img.src!==replacement)img.src=replacement;img.alt="Red Bull Ring dans Assetto Corsa Competizione"}))};fixRedBullRingImage();if(page==="classement.html"){const rankingRoot=document.querySelector("[data-alltime-leaderboard]")||document.body;new MutationObserver((()=>fixRedBullRingImage())).observe(rankingRoot,{childList:true,subtree:true})}document.addEventListener("click",(event=>{if(event.target.closest("[data-language],[data-lang-switch]"))setTimeout((()=>{document.querySelectorAll("[data-fr][data-en]").forEach((el=>{el.textContent=el.dataset[lang()]||el.textContent}));if(track)fetch(`${apiBase}/public-event`,{cache:"no-store"}).then((r=>r.ok?r.json():{})).then((p=>renderTicker(p.events||[]))).catch((()=>{}))}),0)}))})();